style.css:
@-moz-document domain("ecsr.io") {
/* ---------- BASE ---------- */
  html, body {
    background-color: #f6f2ea !important;
    color: #1c1c1c !important;
    font-family:
      "Frank Ruhl Libre",
      "Cardo",
      "Noto Serif Hebrew",
      "Times New Roman",
      serif !important;
  }

  /* ---------- STAR WATERMARK ---------- */
  body::before {
    content: "✡";
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    font-size: 32rem;
    color: rgba(31, 58, 95, 0.025);
    z-index: -1;
    pointer-events: none;
    user-select: none;
  }

  /* ---------- LINKS ---------- */
  a {
    color: #1f3a5f !important;
  }
  a:hover {
    color: #c9a24d !important;
    text-decoration: underline;
  }

  /* ---------- HEADINGS ---------- */
  h1, h2, h3, h4, h5 {
    color: #1f3a5f !important;
    border-bottom: 1px solid #d6cfc2;
    padding-bottom: 0.2em;
  }

  h1::after,
  h2::after,
  h3::after {
    content: " ✡ ";
    color: #c9a24d;
    font-size: 0.8em;
  }

  /* ---------- INPUTS ---------- */
  input, textarea, select {
    background-color: #ece6d8 !important;
    color: #1c1c1c !important;
    border: 1px solid #d6cfc2 !important;
    border-radius: 4px;
  }

  /* ---------- BUTTONS ---------- */
  button, input[type="submit"] {
    background-color: #1f3a5f !important;
    color: #ffffff !important;
    border: none !important;
    border-radius: 6px;
    padding: 6px 12px;
  }

  button:hover {
    background-color: #2f4f75 !important;
  }

  /* ---------- TABLES ---------- */
  table {
    background-color: #ece6d8 !important;
  }
  th {
    background-color: #1f3a5f !important;
    color: white !important;
  }
  td {
    border-color: #d6cfc2 !important;
  }

  /* ---------- BLOCKQUOTES ---------- */
  blockquote {
    border-left: 4px solid #c9a24d !important;
    padding-left: 12px;
    background-color: rgba(201, 162, 77, 0.05);
    position: relative;
  }

  blockquote::before {
    content: "✡";
    position: absolute;
    left: -26px;
    top: 6px;
    color: #c9a24d;
    font-size: 1.1em;
  }

  /* ---------- SCROLLBAR ---------- */
  ::-webkit-scrollbar {
    width: 10px;
  }
  ::-webkit-scrollbar-track {
    background: #ece6d8;
  }
  ::-webkit-scrollbar-thumb {
    background: #1f3a5f;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: #c9a24d;
  }

  /* ---------- HEBREW SUPPORT ---------- */
  [lang="he"], .hebrew, .rtl {
    direction: rtl !important;
    text-align: right !important;
    font-family: "Noto Serif Hebrew", "Frank Ruhl Libre", serif !important;
  }

  /* ---------- TEXT SELECTION ---------- */
  ::selection {
    background: #e3c97a;
    color: #000;
  }
}
